 public string Arguments(string input,string output){Validate();string f="";if(Crop==-1){string detected=DetectCrop(input);if(detected!="")f+="crop="+detected+",";}
  if(Crop>0){string r=CropRatio();f+="crop='min(iw,ih*"+r+")':'min(ih,iw/("+r+"))',";}
  if(Aspect>0){string r=AspectRatio();f+="pad='ceil(max(iw,ih*"+r+"))':'ceil(max(ih,iw/("+r+")))':(ow-iw)/2:(oh-ih)/2:color=black,";}
  f+="fps="+Fps+",scale="+(Dimension==0?Size+":-1":"-1:"+Size)+":flags=lanczos,setsar=1";
  string palette=Method==1?"palettegen[p];[b][p]paletteuse":"palettegen=stats_mode=single[p];[b][p]paletteuse=new=1"+(Method==2?":dither=bayer:bayer_scale=3":"");
  return "-hide_banner -nostdin -y -abort_on empty_output -ss "+N(Start)+" -t "+N(End-Start)+" -i \""+input+"\" -filter_complex \"[0:v]"+f+",split[a][b];[a]"+palette+"\" -an -loop "+Loop+" \""+output+"\"";
 }
}
