 GifOptions ReadOptions(){var o=new GifOptions{Start=D(start.Text),End=Math.Min(D(end.Text),duration),Size=int.Parse(size.Text),Fps=int.Parse(fps.Text),Loop=int.Parse(loop.Text),Dimension=dimension.SelectedIndex,Crop=crop.SelectedIndex==0?0:crop.SelectedIndex==1?-1:crop.SelectedIndex-1,CustomCrop=customCrop.Text,Aspect=aspect.SelectedIndex,CustomAspect=customAspect.Text,Method=method.SelectedIndex,MaxBytes=profile.SelectedIndex==1?10*1024*1024:0};o.Validate();o.AspectRatio();o.CropRatio();if(o.Start>=duration)throw new Exception("Начало находится за пределами видео.");return o;}
 void Save(){try{Result=ReadOptions();DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Настройки GIF");}}
 void RenderMessage(string message){if(!closing&&IsHandleCreated)BeginInvoke(new Action(()=>{if(!closing)renderedStatus.Text=message;}));}
 async Task RenderPreview(bool estimate){if(string.IsNullOrEmpty(input)){MessageBox.Show(this,"Сначала добавьте видео в главном окне.");return;}GifOptions chosen;try{chosen=ReadOptions();}catch(Exception ex){MessageBox.Show(this,ex.Message);return;}string temp=Path.Combine(Path.GetTempPath(),"Forma-preview-"+Guid.NewGuid().ToString("N")+".gif");generation++;try{if(activePreview!=null&&!activePreview.HasExited)activePreview.Kill();}catch{}
  rendering=true;cancelRender=false;estimateButton.Enabled=saveButton.Enabled=timeControls.Enabled=optionControls.Enabled=profile.Enabled=seek.Enabled=false;renderButton.Text="Остановить";double originalDuration=chosen.End-chosen.Start;
  try{if(estimate){chosen.End=chosen.Start+Math.Min(2,originalDuration);chosen.MaxBytes=0;}renderedStatus.Text=estimate?"Считаем по короткому образцу…":"Создаём готовый GIF…";var watch=Stopwatch.StartNew();await Task.Run(()=>GifRender.Render(chosen,input,temp,root,()=>closing||cancelRender,p=>activePreview=p,f=>RenderMessage((estimate?"Оценка":"Предпросмотр")+": "+(int)(f*100)+"%")));
   if(closing||cancelRender){if(!closing)renderedStatus.Text="Остановлено";return;}long bytes=new FileInfo(temp).Length;if(estimate)renderedStatus.Text="Оценка ~"+(bytes*originalDuration/(chosen.End-chosen.Start)/1048576).ToString("0.00")+" МБ · по первым "+(chosen.End-chosen.Start).ToString("0.##")+" с";else{renderedStatus.Text="Готово: "+(bytes/1048576d).ToString("0.00")+" МБ";using(var window=new GifResultWindow(temp))window.ShowDialog(this);}
  }catch(Exception ex){if(!closing)renderedStatus.Text=cancelRender?"Остановлено":ex.Message;}finally{try{File.Delete(temp);}catch{}rendering=false;if(!closing){estimateButton.Enabled=saveButton.Enabled=timeControls.Enabled=optionControls.Enabled=profile.Enabled=true;seek.Enabled=!string.IsNullOrEmpty(input);renderButton.Text="Предпросмотр GIF";}}
 }
 async Task LoadVideo(){if(string.IsNullOrEmpty(input)){duration=86400;notice.Text="Добавьте видео в главном окне, чтобы увидеть предпросмотр.";seek.Enabled=false;return;}try{double value=await Task.Run(()=>{using(var p=new Process()){p.StartInfo=new ProcessStartInfo(Path.Combine(root,"ffprobe.exe"),"-v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 \""+input+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};p.Start();var err=p.StandardError.ReadToEndAsync();string data=p.StandardOutput.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(err.Result);return double.Parse(data.Trim(),CultureInfo.InvariantCulture);}});if(closing)return;if(value>0)duration=value;double finish=Math.Min(Result.End,duration);if(Result.Start>=finish){start.Text="0";finish=Math.Min(5,duration);}end.Text=GifOptions.N(finish);position.Text="Позиция: 0,00 с / "+duration.ToString("0.00")+" с";await Frame();}catch{if(!closing)notice.Text="Предпросмотр недоступен. Укажите время вручную.";}}
 async Task Frame(){if(closing||rendering)return;int version=++generation;double time=Math.Min(current,Math.Max(0,duration-0.05));try{byte[] bytes=await Task.Run(()=>{using(var p=new Process()){p.StartInfo=new ProcessStartInfo(Path.Combine(root,"ffmpeg.exe"),"-v error -ss "+GifOptions.N(time)+" -i \""+input+"\" -frames:v 1 -vf scale=500:-1 -f image2pipe -vcodec mjpeg -"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};activePreview=p;p.Start();if(closing)try{p.Kill();}catch{}var err=p.StandardError.ReadToEndAsync();using(var ms=new MemoryStream()){p.StandardOutput.BaseStream.CopyTo(ms);p.WaitForExit();if(p.ExitCode!=0)throw new Exception(err.Result);return ms.ToArray();}}});if(closing||version!=generation)return;using(var ms=new MemoryStream(bytes))using(var image=Image.FromStream(ms)){var old=preview.Image;preview.Image=new Bitmap(image);if(old!=null)old.Dispose();}notice.Text="Перемещайте ползунок, затем подставьте позицию в начало или конец.";}catch{if(!closing&&version==generation)notice.Text="Этот кадр недоступен. Попробуйте другую позицию.";}}
